function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 50 + 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2, H / 2 - 30 + 20 * Math.sin(t));
  ctx.lineTo(W / 2 - 20 + 10 * Math.cos(t), H / 2 - 10 + 20 * Math.sin(t));
  ctx.lineTo(W / 2 + 20 + 10 * Math.cos(t), H / 2 - 10 + 20 * Math.sin(t));
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W / 2 + 100, H / 2 + 50 + 10 * Math.sin(t), 15, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H / 2 + 35 + 10 * Math.sin(t));
  ctx.lineTo(W / 2 + 80 + 5 * Math.cos(t), H / 2 + 45 + 10 * Math.sin(t));
  ctx.lineTo(W / 2 + 120 + 5 * Math.cos(t), H / 2 + 45 + 10 * Math.sin(t));
  ctx.stroke();

  // rabbit
  ctx.beginPath();
  ctx.arc(W / 2 - 100, H / 2 + 50 - 10 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 - 100, H / 2 + 30 - 10 * Math.sin(t));
  ctx.lineTo(W / 2 - 120 - 10 * Math.cos(t), H / 2 + 50 - 10 * Math.sin(t));
  ctx.lineTo(W / 2 - 80 - 10 * Math.cos(t), H / 2 + 50 - 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
